export enum AppLanguage {
  CN = 'zh-CN',
  EN = 'en-US',
  LAO = 'lo-LA'
}

export interface TranslationState {
  isProcessing: boolean;
  currentPage: number;
  totalPages: number;
  sourceFiles: string[]; // Base64 strings of pages
  translatedMarkdown: string;
  error: string | null;
  originalFileName: string | null;
}

export interface UIContent {
  title: string;
  upload: string;
  stop: string;
  reset: string;
  saveToDrive: string;
  downloadMd: string;
  prevPage: string;
  nextPage: string;
  pageIndicator: (current: number, total: number) => string;
  errorTitle: string;
  retry: string;
  dropzoneText: string;
  processingText: string;
}

export type I18nData = Record<AppLanguage, UIContent>;

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SYSTEM_PROMPT, GEMINI_MODEL } from "../constants";

export async function translatePage(
  base64Image: string,
  onChunk?: (text: string) => void,
  abortSignal?: AbortSignal
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const imagePart = {
    inlineData: {
      mimeType: "image/jpeg",
      data: base64Image,
    },
  };

  const stream = await ai.models.generateContentStream({
    model: GEMINI_MODEL,
    contents: [{ parts: [imagePart, { text: "Please OCR and translate this document page according to your instructions. Output Markdown ONLY." }] }],
    config: {
      systemInstruction: SYSTEM_PROMPT,
      temperature: 0.1, // Lower temperature for more consistent OCR/Translation
    },
  });

  let fullText = "";
  for await (const chunk of stream) {
    if (abortSignal?.aborted) break;
    const text = (chunk as GenerateContentResponse).text || "";
    fullText += text;
    onChunk?.(text);
  }

  return fullText;
}

// Manual implementation of encode/decode as required
export function encode(bytes: Uint8Array): string {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const base64 = reader.result?.toString().split(',')[1];
      if (base64) resolve(base64);
      else reject(new Error("Failed to convert file to base64"));
    };
    reader.onerror = error => reject(error);
  });
}

/**
 * Since standard PDF libraries can be large, for this SPA we simulate page splitting
 * In a real-world scenario, you would use pdfjs-dist to render each page to a canvas, then to base64.
 * For now, if it's a multi-page PDF, we treat it as one image or prompt for images.
 */
export async function pdfToImages(file: File): Promise<string[]> {
  // Mocking PDF splitting logic
  // In a real environment, you'd use: 
  // const pdf = await pdfjs.getDocument(url).promise;
  // for(let i=1; i<=pdf.numPages; i++) { ... render to canvas ... }
  const b64 = await fileToBase64(file);
  return [b64]; 
}

export function downloadMarkdown(content: string, filename: string) {
  const blob = new Blob([content], { type: 'text/markdown;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

import React from 'react';

interface MarkdownViewerProps {
  content: string;
}

// Simple Markdown to HTML logic for rendering
const MarkdownViewer: React.FC<MarkdownViewerProps> = ({ content }) => {
  // In a production app, use a library like 'react-markdown'. 
  // Here we manually handle basic tables and formatting to meet the single-file/minimal-dependency spirit.

  const parseMarkdown = (md: string) => {
    let html = md
      .replace(/^# (.*$)/gim, '<h1 class="text-3xl font-bold my-4">$1</h1>')
      .replace(/^## (.*$)/gim, '<h2 class="text-2xl font-semibold my-3">$1</h2>')
      .replace(/^### (.*$)/gim, '<h3 class="text-xl font-medium my-2">$1</h3>')
      .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
      .replace(/\*(.*?)\*/gim, '<em>$1</em>')
      .replace(/^\- (.*$)/gim, '<li class="ml-4 list-disc">$1</li>')
      .replace(/\n/g, '<br />');

    // Simple table parser
    const tableRegex = /\|(.+)\|[\n\r]\|(?:[ :\-]+|)\|[\n\r]((?:\|.+\|[\n\r]*)+)/g;
    html = html.replace(tableRegex, (match) => {
      const rows = match.trim().split('\n');
      const headers = rows[0].split('|').filter(c => c.trim() !== '').map(h => `<th class="border px-4 py-2 bg-slate-100 font-bold">${h.trim()}</th>`).join('');
      const body = rows.slice(2).map(row => {
        const cols = row.split('|').filter(c => c.trim() !== '').map(c => `<td class="border px-4 py-2">${c.trim()}</td>`).join('');
        return `<tr>${cols}</tr>`;
      }).join('');
      return `<div class="overflow-x-auto my-4"><table class="min-w-full border-collapse border border-slate-300"><thead><tr>${headers}</tr></thead><tbody>${body}</tbody></table></div>`;
    });

    return html;
  };

  return (
    <div 
      className="prose max-w-none text-slate-800 lao-text"
      dangerouslySetInnerHTML={{ __html: parseMarkdown(content) }}
    />
  );
};

export default MarkdownViewer;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { AppLanguage, TranslationState } from './types';
import { I18N } from './constants';
import { translatePage } from './services/geminiService';
import { fileToBase64, downloadMarkdown } from './utils/fileUtils';
