const App: React.FC = () => {
  const [lang, setLang] = useState<AppLanguage>(AppLanguage.CN);
  const [state, setState] = useState<TranslationState>({
    isProcessing: false,
    currentPage: 1,
    totalPages: 0,
    sourceFiles: [],
    translatedMarkdown: "",
    error: null,
    originalFileName: null,
  });

  const abortControllerRef = useRef<AbortController | null>(null);
  const ui = I18N[lang];

  // Persist language preference
  useEffect(() => {
    const savedLang = localStorage.getItem('laoDocLang') as AppLanguage;
    if (savedLang && Object.values(AppLanguage).includes(savedLang)) {
      setLang(savedLang);
    } else {
      const browserLang = navigator.language;
      if (browserLang.includes('lo')) setLang(AppLanguage.LAO);
      else if (browserLang.includes('en')) setLang(AppLanguage.EN);
    }
  }, []);

  const handleLangChange = (newLang: AppLanguage) => {
    setLang(newLang);
    localStorage.setItem('laoDocLang', newLang);
  };

  const resetAll = () => {
    abortControllerRef.current?.abort();
    setState({
      isProcessing: false,
      currentPage: 1,
      totalPages: 0,
      sourceFiles: [],
      translatedMarkdown: "",
      error: null,
      originalFileName: null,
    });
  };

  const stopTranslation = () => {
    abortControllerRef.current?.abort();
    setState(prev => ({ ...prev, isProcessing: false }));
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    resetAll();
    setState(prev => ({ 
      ...prev, 
      isProcessing: true, 
      originalFileName: file.name 
    }));

    try {
      // For images/PDFs - in this SPA we treat single upload as 1 page for simplicity
      // Real-world would use pdfjs to split pages.
      const base64 = await fileToBase64(file);
      setState(prev => ({
        ...prev,
        sourceFiles: [base64],
        totalPages: 1
      }));

      abortControllerRef.current = new AbortController();

      await translatePage(
        base64, 
        (chunk) => {
          setState(prev => ({
            ...prev,
            translatedMarkdown: prev.translatedMarkdown + chunk
          }));
        },
        abortControllerRef.current.signal
      );

      setState(prev => ({ ...prev, isProcessing: false }));
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        setState(prev => ({ 
          ...prev, 
          error: err.message, 
          isProcessing: false 
        }));
      }
    }
  };

  const saveToGoogleDrive = () => {
    // Simulated Google Workspace integration
    alert("正在保存至 Google Drive... (功能需 Workspace API 权限)");
  };

  const handleDownload = () => {
    const name = state.originalFileName ? state.originalFileName.split('.')[0] : 'document';
    downloadMarkdown(state.translatedMarkdown, `${name}-中译稿.md`);
  };

  return (
    <div className="flex flex-col h-screen bg-[#F5F5F5] overflow-hidden">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-[#1A2B3C]/95 backdrop-blur-md text-white border-b border-white/10 shadow-lg px-6 py-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-teal-500 rounded-lg flex items-center justify-center shadow-inner">
            <span className="text-xl font-bold">L</span>
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">{ui.title}</h1>
            <p className="text-xs text-slate-400 font-medium">Professional High-Precision OCR & Translation</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center bg-white/10 rounded-full px-3 py-1.5 border border-white/20">
            <Icons.Globe />
            <select 
              value={lang} 
              onChange={(e) => handleLangChange(e.target.value as AppLanguage)}
              className="bg-transparent border-none text-sm font-medium focus:ring-0 cursor-pointer ml-2 outline-none"
            >
              <option value={AppLanguage.CN} className="text-black">中文</option>
              <option value={AppLanguage.EN} className="text-black">English</option>
              <option value={AppLanguage.LAO} className="text-black">ລາວ</option>
            </select>
          </div>
        </div>
      </header>

      {/* Main Layout */}
      <main className="flex-1 flex overflow-hidden">
        {/* Sidebar Controls */}
        <aside className="w-72 bg-white border-r border-slate-200 flex flex-col p-6 shadow-[4px_0_24px_rgba(0,0,0,0.02)] z-10">
          <div className="space-y-4">
            <label className="group relative flex flex-col items-center justify-center w-full h-40 border-2 border-dashed border-slate-300 rounded-xl hover:border-teal-500 hover:bg-teal-50/30 transition-all cursor-pointer">
              <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center px-4">
                <div className="mb-3 text-slate-400 group-hover:text-teal-500 transition-colors">
                  <Icons.Upload />
                </div>
                <p className="text-xs font-semibold text-slate-600 group-hover:text-teal-600">{ui.dropzoneText}</p>
              </div>
              <input type="file" className="hidden" accept="application/pdf,image/*" onChange={handleFileUpload} />
            </label>

            <div className="grid grid-cols-1 gap-3 pt-4">
              <button 
                onClick={stopTranslation}
                disabled={!state.isProcessing}
                className="flex items-center justify-center gap-2 px-4 py-2.5 bg-rose-50 text-rose-600 rounded-lg font-semibold hover:bg-rose-100 disabled:opacity-50 transition-colors text-sm"
              >
                <Icons.Stop /> {ui.stop}
              </button>

              <button 
                onClick={resetAll}
                className="flex items-center justify-center gap-2 px-4 py-2.5 bg-slate-100 text-slate-600 rounded-lg font-semibold hover:bg-slate-200 transition-colors text-sm"
              >
                <Icons.Reset /> {ui.reset}
              </button>

              <hr className="my-2 border-slate-100" />

              <button 
                onClick={saveToGoogleDrive}
                disabled={!state.translatedMarkdown}
                className="flex items-center justify-center gap-2 px-4 py-2.5 bg-sky-50 text-sky-700 rounded-lg font-semibold hover:bg-sky-100 disabled:opacity-50 transition-colors text-sm"
              >
                <Icons.Drive /> {ui.saveToDrive}
              </button>

              <button 
                onClick={handleDownload}
                disabled={!state.translatedMarkdown}
                className="flex items-center justify-center gap-2 px-4 py-2.5 bg-teal-600 text-white rounded-lg font-semibold hover:bg-teal-700 disabled:opacity-50 shadow-md shadow-teal-500/20 transition-all text-sm"
              >
                <Icons.Download /> {ui.downloadMd}
              </button>
            </div>
          </div>

          <div className="mt-auto pt-6 text-center">
            <p className="text-[10px] text-slate-400 uppercase tracking-widest font-bold">Document Processing Node</p>
            <p className="text-[10px] text-teal-600 font-mono mt-1">Status: {state.isProcessing ? 'BUSY' : 'IDLE'}</p>
          </div>
        </aside>

        {/* Dual Pane Comparator */}
        <section className="flex-1 flex overflow-hidden relative">

          {/* Source Pane */}
          <div className="w-1/2 flex flex-col border-r border-slate-200 bg-slate-50">
            <div className="p-3 bg-slate-200/50 flex justify-between items-center text-xs font-bold text-slate-500 uppercase tracking-wider">
              <span>Original Document (Source)</span>
              {state.totalPages > 0 && <span>{ui.pageIndicator(state.currentPage, state.totalPages)}</span>}
            </div>
            <div className="flex-1 overflow-auto p-8 flex justify-center">
              {state.sourceFiles.length > 0 ? (
                <img 
                  src={`data:image/jpeg;base64,${state.sourceFiles[state.currentPage - 1]}`} 
                  alt="Source" 
                  className="max-w-full h-auto shadow-2xl rounded-sm border border-slate-200"
                />
              ) : (
                <div className="flex flex-col items-center justify-center text-slate-300 mt-20">
                  <Icons.Upload />
                  <p className="mt-4 text-sm font-medium">Waiting for document...</p>
                </div>
              )}
            </div>
          </div>

          {/* Result Pane */}
          <div className="w-1/2 flex flex-col bg-white">
            <div className="p-3 bg-white flex justify-between items-center text-xs font-bold text-teal-600 uppercase tracking-wider border-b border-slate-100">
              <span>Translated Markdown (Output)</span>
              {state.isProcessing && (
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-teal-500 rounded-full animate-pulse"></div>
                  <span className="text-teal-500 lowercase normal-case">{ui.processingText}</span>
                </div>
              )}
            </div>
            <div className="flex-1 overflow-auto p-12">
              {state.error ? (
                <div className="max-w-md mx-auto mt-20 text-center bg-rose-50 p-8 rounded-2xl border border-rose-100">
                   <div className="inline-block p-4 bg-rose-100 text-rose-600 rounded-full mb-4">
                     <Icons.Stop />
                   </div>
                   <h3 className="text-lg font-bold text-rose-900 mb-2">{ui.errorTitle}</h3>
                   <p className="text-sm text-rose-700 mb-6">{state.error}</p>
                   <button onClick={resetAll} className="px-6 py-2 bg-rose-600 text-white rounded-lg font-bold hover:bg-rose-700 transition-colors">
                     {ui.retry}
                   </button>
                </div>
              ) : state.translatedMarkdown ? (
                <MarkdownViewer content={state.translatedMarkdown} />
              ) : (
                <div className="flex flex-col items-center justify-center text-slate-300 mt-20">
                  <Icons.Download />
                  <p className="mt-4 text-sm font-medium">Translation will appear here</p>
                </div>
              )}
            </div>
          </div>

          {/* Navigation Overlay (Sticky at bottom center) */}
          {state.totalPages > 1 && (
            <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-white/90 backdrop-blur shadow-xl border border-slate-200 px-6 py-3 rounded-full z-20">
              <button 
                onClick={() => setState(s => ({ ...s, currentPage: Math.max(1, s.currentPage - 1) }))}
                disabled={state.currentPage === 1}
                className="text-sm font-bold text-slate-600 hover:text-teal-600 disabled:opacity-30"
              >
                {ui.prevPage}
              </button>
              <span className="text-sm font-mono font-bold border-x border-slate-200 px-4">{state.currentPage} / {state.totalPages}</span>
              <button 
                onClick={() => setState(s => ({ ...s, currentPage: Math.min(s.totalPages, s.currentPage + 1) }))}
                disabled={state.currentPage === state.totalPages}
                className="text-sm font-bold text-slate-600 hover:text-teal-600 disabled:opacity-30"
              >
                {ui.nextPage}
              </button>
            </div>
          )}
        </section>
      </main>

      {/* Footer / Status Bar */}
      <footer className="bg-white border-t border-slate-200 px-6 py-2 flex items-center justify-between text-[10px] text-slate-400 font-bold uppercase tracking-widest">
        <div className="flex gap-4">
          <span>AI Model: {GEMINI_MODEL}</span>
          <span className="text-slate-200">|</span>
          <span>OCR Engine: Multimodal V3</span>
        </div>
        <div className="flex items-center gap-2">
          <div className={`w-1.5 h-1.5 rounded-full ${state.isProcessing ? 'bg-amber-400' : 'bg-emerald-400'}`}></div>
          <span>System Status: Optimal</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

