import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { SYSTEM_PROMPT, GEMINI_MODEL } from "../constants";

export async function translatePage(
  base64Data: string,
  mimeType: string,
  onChunk?: (text: string) => void,
  abortSignal?: AbortSignal
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const mediaPart = {
    inlineData: {
      mimeType: mimeType,
      data: base64Data,
    },
  };

  const stream = await ai.models.generateContentStream({
    model: GEMINI_MODEL,
    contents: [{ parts: [mediaPart, { text: "Please OCR and translate this document according to your instructions. Focus on maintaining table structures and layout. Output Markdown ONLY." }] }],
    config: {
      systemInstruction: SYSTEM_PROMPT,
      temperature: 0.1,
    },
  });

  let fullText = "";
  try {
    for await (const chunk of stream) {
      if (abortSignal?.aborted) break;
      const text = (chunk as GenerateContentResponse).text || "";
      fullText += text;
      onChunk?.(text);
    }
  } catch (error: any) {
    if (error.name === 'AbortError') return fullText;
    throw error;
  }

  return fullText;
}

