const Icons = {
  Upload: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>,
  Play: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8.118v3.764a1 1 0 001.555.832l3.197-1.882a1 1 0 000-1.664l-3.197-1.882z" clipRule="evenodd" /></svg>,
  Stop: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" /></svg>,
  Reset: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>,
  Download: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>,
  Drive: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" /></svg>,
  Globe: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3.6 9h16.8M3.6 15h16.8M12 3a18.85 18.85 0 00-3.1 9 18.85 18.85 0 003.1 9 18.85 18.85 0 003.1-9A18.85 18.85 0 0012 3z" /></svg>,
  Error: () => <svg xmlns="http://www.w3.org/2000/svg" className="w-12 h-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
};

const App: React.FC = () => {
  const [lang, setLang] = useState<AppLanguage>(AppLanguage.CN);
  const [state, setState] = useState<TranslationState>({
    isProcessing: false,
    currentPage: 1,
    totalPages: 0,
    sourceFiles: [],
    translatedMarkdown: "",
    error: null,
    originalFileName: null,
  });

  const abortControllerRef = useRef<AbortController | null>(null);
  const ui = I18N[lang];

  useEffect(() => {
    const savedLang = localStorage.getItem('laoDocLang') as AppLanguage;
    if (savedLang && Object.values(AppLanguage).includes(savedLang)) {
      setLang(savedLang);
    } else {
      const browserLang = navigator.language;
      if (browserLang.includes('lo')) setLang(AppLanguage.LAO);
      else if (browserLang.includes('en')) setLang(AppLanguage.EN);
    }
  }, []);

  const handleLangChange = (newLang: AppLanguage) => {
    setLang(newLang);
    localStorage.setItem('laoDocLang', newLang);
  };

  const resetAll = () => {
    abortControllerRef.current?.abort();
    setState({
      isProcessing: false,
      currentPage: 1,
      totalPages: 0,
      sourceFiles: [],
      translatedMarkdown: "",
      error: null,
      originalFileName: null,
    });
  };

  const stopTranslation = () => {
    abortControllerRef.current?.abort();
    setState(prev => ({ ...prev, isProcessing: false }));
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    resetAll();

    try {
      const base64 = await fileToBase64(file);
      setState(prev => ({
        ...prev,
        sourceFiles: [base64],
        totalPages: 1,
        originalFileName: file.name,
      }));
    } catch (err: any) {
        setState(prev => ({ ...prev, error: err.message || "Failed to load file." }));
    }
  };

  const handleStartTranslation = async () => {
    if (state.sourceFiles.length === 0 || state.isProcessing) return;

    setState(prev => ({
        ...prev,
        isProcessing: true,
        translatedMarkdown: "",
        error: null,
    }));

    abortControllerRef.current = new AbortController();
    const mimeType = state.originalFileName?.toLowerCase().endsWith('.pdf') ? 'application/pdf' : 'image/jpeg';

    try {
      await translatePage(
        state.sourceFiles[0],
        mimeType,
        (chunk) => {
          setState(prev => ({
            ...prev,
            translatedMarkdown: prev.translatedMarkdown + chunk
          }));
        },
        abortControllerRef.current.signal
      );
      setState(prev => ({ ...prev, isProcessing: false }));
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        setState(prev => ({ 
          ...prev, 
          error: err.message || "An unexpected error occurred", 
          isProcessing: false 
        }));
      }
    }
  };

  const saveToGoogleDrive = () => {
    alert("正在保存至 Google Drive... (功能需 Workspace API 权限)");
  };

  const handleDownload = () => {
    const name = state.originalFileName ? state.originalFileName.split('.')[0] : 'document';
    downloadMarkdown(state.translatedMarkdown, `${name}-中译稿.md`);
  };

  return (
    <div className="flex flex-col h-screen bg-[#F8FAFC] overflow-hidden text-slate-900">
      <header className="sticky top-0 z-50 bg-[#0F172A] text-white shadow-xl px-6 py-4 flex items-center justify-between border-b border-slate-800">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-gradient-to-br from-teal-400 to-emerald-600 rounded-xl flex items-center justify-center shadow-lg transform rotate-3">
            <span className="text-xl font-black italic">L</span>
          </div>
          <div>
            <h1 className="text-xl font-extrabold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">{ui.title}</h1>
            <p className="text-[10px] text-teal-400 font-bold uppercase tracking-widest opacity-80">Enterprise Multimodal Workflow</p>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="flex items-center bg-slate-800/50 rounded-full px-4 py-1.5 border border-slate-700">
            <Icons.Globe />
            <select 
              value={lang} 
              onChange={(e) => handleLangChange(e.target.value as AppLanguage)}
              className="bg-transparent border-none text-xs font-bold focus:ring-0 cursor-pointer ml-2 outline-none uppercase"
            >
              <option value={AppLanguage.CN} className="text-black">CN</option>
              <option value={AppLanguage.EN} className="text-black">EN</option>
              <option value={AppLanguage.LAO} className="text-black">LO</option>
            </select>
          </div>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-72 bg-white border-r border-slate-200 flex flex-col shadow-[1px_0_10px_rgba(0,0,0,0.03)] z-10 overflow-y-auto">
          <div className="p-6 space-y-6">
            <section>
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">上传文档</h3>
              <label className="group relative flex flex-col items-center justify-center w-full h-40 border-2 border-dashed border-slate-200 rounded-2xl hover:border-teal-500 hover:bg-teal-50/30 transition-all cursor-pointer shadow-sm">
                <div className="flex flex-col items-center justify-center pt-5 pb-6 text-center px-4">
                  <div className="mb-3 text-slate-300 group-hover:text-teal-500 transition-colors transform group-hover:scale-110 duration-200">
                    <Icons.Upload />
                  </div>
                  <p className="text-[11px] font-bold text-slate-500 group-hover:text-teal-600 leading-tight">{ui.dropzoneText}</p>
                </div>
                <input type="file" className="hidden" accept="application/pdf,image/*" onChange={handleFileUpload} />
              </label>
            </section>

            <section className="space-y-3">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">流程控制</h3>
              <button 
                onClick={handleStartTranslation}
                disabled={state.sourceFiles.length === 0 || state.isProcessing}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-emerald-500 text-white rounded-xl font-bold hover:bg-emerald-600 disabled:opacity-40 shadow-lg shadow-emerald-500/20 transition-all text-sm"
              >
                <Icons.Play /> {ui.startExecution}
              </button>
              <button 
                onClick={stopTranslation}
                disabled={!state.isProcessing}
                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-rose-50 text-rose-600 rounded-xl font-bold hover:bg-rose-100 disabled:opacity-40 transition-all text-xs border border-rose-100"
              >
                <Icons.Stop /> {ui.stop}
              </button>
              <button 
                onClick={resetAll}
                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-slate-50 text-slate-600 rounded-xl font-bold hover:bg-slate-100 transition-all text-xs border border-slate-100"
              >
                <Icons.Reset /> {ui.reset}
              </button>
            </section>

            <section className="space-y-3 pt-2">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">导出选项</h3>
              <button 
                onClick={saveToGoogleDrive}
                disabled={!state.translatedMarkdown}
                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-sky-50 text-sky-700 rounded-xl font-bold hover:bg-sky-100 disabled:opacity-40 transition-all text-xs border border-sky-100"
              >
                <Icons.Drive /> {ui.saveToDrive}
              </button>
              <button 
                onClick={handleDownload}
                disabled={!state.translatedMarkdown}
                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-teal-600 text-white rounded-xl font-bold hover:bg-teal-700 disabled:opacity-40 shadow-lg shadow-teal-500/20 transition-all text-xs"
              >
                <Icons.Download /> {ui.downloadMd}
              </button>
            </section>
          </div>

          <div className="mt-auto p-6 bg-slate-50 border-t border-slate-100">
            <div className="flex items-center gap-2 mb-1">
              <div className={`w-2 h-2 rounded-full ${state.isProcessing ? 'bg-amber-400 animate-pulse' : (state.sourceFiles.length > 0 ? 'bg-sky-500' : 'bg-slate-400')}`}></div>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">{state.isProcessing ? 'Processing' : (state.sourceFiles.length > 0 ? 'Ready to Start' : 'Idle')}</p>
            </div>
            <p className="text-[9px] text-slate-400 font-mono break-all">{GEMINI_MODEL}</p>
          </div>
        </aside>

        <section className="flex-1 flex overflow-hidden relative bg-slate-100/50">
          <div className="w-1/2 flex flex-col border-r border-slate-200">
            <div className="h-10 px-4 bg-slate-200/40 flex justify-between items-center border-b border-slate-200">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">原文预览 / SOURCE</span>
              {state.totalPages > 0 && <span className="text-[10px] font-bold bg-slate-300 px-2 py-0.5 rounded text-slate-600">{ui.pageIndicator(state.currentPage, state.totalPages)}</span>}
            </div>
            <div className="flex-1 overflow-auto p-12 bg-slate-200/20 flex justify-center items-start">
              {state.sourceFiles.length > 0 ? (
                state.originalFileName?.toLowerCase().endsWith('.pdf') ? (
                  <iframe 
                    src={`data:application/pdf;base64,${state.sourceFiles[0]}#toolbar=0`} 
                    className="w-full max-w-2xl h-[calc(100vh-160px)] shadow-2xl bg-white border border-slate-300"
                    title="PDF"
                  />
                ) : (
                  <img 
                    src={`data:image/jpeg;base64,${state.sourceFiles[state.currentPage - 1]}`} 
                    alt="Source" 
                    className="max-w-full shadow-2xl border border-slate-300 rounded-sm"
                  />
                )
              ) : (
                <div className="mt-32 flex flex-col items-center opacity-20 grayscale">
                  <Icons.Upload />
                  <p className="mt-4 font-black uppercase text-xl">Idle Workspace</p>
                </div>
              )}
            </div>
          </div>

          <div className="w-1/2 flex flex-col bg-white">
            <div className="h-10 px-4 bg-teal-500/5 flex justify-between items-center border-b border-teal-500/10">
              <span className="text-[10px] font-black text-teal-600 uppercase tracking-widest">译文输出 / TRANSLATION</span>
              {state.isProcessing && (
                <div className="flex items-center gap-2">
                  <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-ping"></span>
                  <span className="text-[10px] font-bold text-teal-500">{ui.processingText}</span>
                </div>
              )}
            </div>
            <div className="flex-1 overflow-auto p-12 bg-white relative">
              {state.error ? (
                <div className="max-w-lg mx-auto mt-20 p-10 bg-rose-50 rounded-3xl border border-rose-100 text-center shadow-sm">
                   <div className="inline-flex items-center justify-center p-5 bg-rose-100 text-rose-600 rounded-full mb-6">
                     <Icons.Error />
                   </div>
                   <h3 className="text-xl font-black text-rose-900 mb-3">{ui.errorTitle}</h3>
                   <div className="text-sm text-rose-700 leading-relaxed mb-8 bg-white/50 p-6 rounded-2xl border border-rose-100 text-left font-medium">
                     {state.error}
                     <div className="mt-4 pt-4 border-t border-rose-100 text-[11px] font-bold text-rose-400 uppercase">
                       建议：检查文件是否损坏，或尝试转换格式为 JPG/PNG 后上传。
                     </div>
                   </div>
                   <button onClick={resetAll} className="px-10 py-3 bg-rose-600 text-white rounded-xl font-bold hover:bg-rose-700 transform hover:scale-105 transition-all shadow-lg shadow-rose-200">
                     {ui.retry}
                   </button>
                </div>
              ) : state.translatedMarkdown ? (
                <div className="max-w-3xl mx-auto min-h-full bg-white shadow-[0_0_50px_rgba(0,0,0,0.05)] border border-slate-100 p-12 rounded-sm transform transition-all duration-700">
                  <MarkdownViewer content={state.translatedMarkdown} />
                  {state.isProcessing && (
                    <div className="mt-8 pt-8 border-t border-slate-100 animate-pulse flex flex-col gap-2">
                      <div className="h-4 bg-slate-100 rounded w-full"></div>
                      <div className="h-4 bg-slate-100 rounded w-5/6"></div>
                      <div className="h-4 bg-slate-100 rounded w-4/6"></div>
                    </div>
                  )}
                </div>
              ) : (
                <div className="mt-32 flex flex-col items-center opacity-20 grayscale">
                  <Icons.Download />
                  <p className="mt-4 font-black uppercase text-xl">Output Stream</p>
                </div>
              )}
            </div>
          </div>
        </section>
      </main>

      <footer className="bg-[#0F172A] border-t border-slate-800 px-6 py-2 flex items-center justify-between text-[9px] font-bold text-slate-500 uppercase tracking-[0.2em]">
        <div className="flex gap-6">
          <span className="flex items-center gap-2"><span className="w-1 h-1 bg-teal-500 rounded-full"></span> Model: {GEMINI_MODEL}</span>
          <span className="flex items-center gap-2"><span className="w-1 h-1 bg-teal-500 rounded-full"></span> Logic: Multi-Turn Semantic Map</span>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-slate-600">Encrypted Workflow</span>
          <span className="text-teal-900">•</span>
          <span className="text-emerald-500">Secure Session</span>
        </div>
      </footer>
    </div>
  );
};

export default App;
